// Code coverage of unit tests with Kover.
// Reports: `koverHtmlReport` / `koverXmlReport` (JVM), `koverHtmlReportDebug` / `koverXmlReportDebug` (Android).

plugins {
    id("org.jetbrains.kotlinx.kover")
}

kover {
    reports {
        filters {
            excludes {
                // Code generated by Room and shared test fixtures are not production logic.
                classes("*_Impl", "*_Impl\$*", "com.usatov.aura.logger.core.testing.*")
            }
        }
    }
}
